<script setup lang="ts">
import {computed,ref} from 'vue';
import type {DraftInput} from '@loreviva/sdk-ts';
const props=defineProps<{draft:DraftInput;selectedId:string}>();
const emit=defineEmits<{select:[string];move:[string,number,number]}>();
const svg=ref<SVGSVGElement>();const dragging=ref<string>();
const nodes=computed(()=>props.draft.objects.filter(o=>o.kind==='SCENE'||o.kind==='PROP'));
const edges=computed(()=>nodes.value.flatMap(o=>o.kind==='SCENE'?o.adjacent_scene_refs.flatMap(ref=>{const other=nodes.value.find(n=>ref.kind==='LOCAL_DRAFT'&&n.object_id===ref.object_id);return other?[{id:o.object_id+'/'+other.object_id,from:position(o),to:position(other)}]:[]}):[]));
const position=(o:typeof nodes.value[number])=>'position'in o?o.position:{x:0,y:0};
function keyboard(event:KeyboardEvent,o:typeof nodes.value[number]){const delta:Record<string,[number,number]>={ArrowRight:[1,0],ArrowLeft:[-1,0],ArrowDown:[0,1],ArrowUp:[0,-1]};const d=delta[event.key];if(d){event.preventDefault();const p=position(o);emit('move',o.object_id,p.x+d[0],p.y+d[1])}else if(event.key==='Enter'||event.key===' '){event.preventDefault();emit('select',o.object_id)}}
function pointer(event:PointerEvent){if(!dragging.value||!svg.value)return;const matrix=svg.value.getScreenCTM();if(!matrix)return;const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());emit('move',dragging.value,Math.round(p.x-250),Math.round(p.y-170))}
function start(event:PointerEvent,id:string){dragging.value=id;emit('select',id);(event.currentTarget as Element).setPointerCapture(event.pointerId)}
</script>
<template><section class="stage"><div class="section-heading"><h2>场景舞台</h2><span class="badge">2D / 2.5D</span></div><p class="muted">选择场景或道具；拖动或用方向键调整位置。位置表单可完成相同操作。</p><svg ref="svg" role="img" aria-label="场景与道具位置" viewBox="0 0 500 340" @pointermove="pointer" @pointerup="dragging=undefined" @pointercancel="dragging=undefined"><defs><pattern id="stage-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="currentColor" stroke-width=".4"/></pattern></defs><rect width="500" height="340" fill="url(#stage-grid)" opacity=".3"/><line v-for="edge in edges" :key="edge.id" :x1="edge.from.x+250" :y1="edge.from.y+170" :x2="edge.to.x+250" :y2="edge.to.y+170" stroke="#7da591" stroke-width="2"/><g v-for="o in nodes" :key="o.object_id" :data-object="o.object_id" :transform="`translate(${position(o).x+250} ${position(o).y+170})`" tabindex="0" role="button" :aria-label="o.name+'，位置 '+position(o).x+'，'+position(o).y" :aria-pressed="selectedId===o.object_id" @click="emit('select',o.object_id)" @keydown="keyboard($event,o)" @pointerdown="start($event,o.object_id)"><rect x="-46" y="-25" width="92" height="50" rx="8" :class="{selected:selectedId===o.object_id}"/><text text-anchor="middle" y="5">{{o.name.slice(0,10)}}</text><text v-if="position(o).z!==undefined" text-anchor="middle" y="19" class="stage-layer">层位 {{position(o).z}}</text></g></svg><p class="caption">确定字段预览：场景、坐标与绑定。原核准表现需要真实结果；新 Mock 试演是独立任务。</p></section></template>
